package com.rwi.myrepublic.astri.internal;import com.rwi.myrepublic.astri.AstriConfig;import java.io.IOException;import java.net.URI;import java.net.URLEncoder;import java.net.http.HttpClient;import java.net.http.HttpRequest;import java.net.http.HttpResponse;import java.nio.charset.StandardCharsets;import java.time.Duration;import java.util.Base64;public class OltClient{private HttpClient client;private AstriConfig config;private String authHeader;public
OltClient(){this.config=AstriConfig.getInstance();this.client=HttpClient.newBuilder().connectTimeout(Duration.ofMillis(config.getConnectionTimeout())).build();String credentials=config.getUsername()+ ":"+config.getPassword();this.authHeader= "Basic "+Base64.getEncoder().encodeToString(credentials.getBytes());}public String getOltList(int limit,int offset,String deviceCode,String name,String label)throws IOException,InterruptedException{String baseUrl=config.getApiBaseUrl();String path=
"/olt/rollout/list/all/"+limit+ "/"+offset;StringBuilder queryParams=new StringBuilder();if(deviceCode!=null&&!deviceCode.isEmpty()){appendParam(queryParams, "device_code",deviceCode);}if(name!=null&&!name.isEmpty()){appendParam(queryParams, "name",name);}if(label!=null&&!label.isEmpty()){appendParam(queryParams, "label",label);}String url=baseUrl+path;if(queryParams.length()>0){url+= "?"+queryParams.toString();}HttpRequest
request=HttpRequest.newBuilder().uri(URI.create(url)).header("Authorization",authHeader).header("Content-Type", "application/json").timeout(Duration.ofMillis(config.getRequestTimeout())).POST(HttpRequest.BodyPublishers.noBody()).build();HttpResponse<String>response=client.send(request,HttpResponse.BodyHandlers.ofString());return response.body();}private void appendParam(StringBuilder sb,String key,String
value){if(sb.length()>0){sb.append("&");}sb.append(URLEncoder.encode(key,StandardCharsets.UTF_8)).append("=").append(URLEncoder.encode(value,StandardCharsets.UTF_8));}public void close(){}}